const isPrime = (n) => {
  // Handle edge cases
  if (n < 2) return false;
  if (n === 2) return true;
  if (n % 2 === 0) return false;

  // Only check odd divisors up to square root
  for (let i = 3; i <= Math.sqrt(n); i += 2) {
    if (n % i === 0) return false;
  }

  return true;
};

