  if (!arr || arr.length === 0) {
    return null;
  }

  // Start with the first element as the initial maximum
  let max = arr[0];

  // Iterate through the remaining elements
  for (let i = 1; i < arr.length; i++) {
    // Update max if a larger value is found
    if (arr[i] > max) {
